// QuotationServiceServer is the server API for QuotationService service.
// All implementations must embed UnimplementedQuotationServiceServer
// for forward compatibility.
type QuotationServiceServer interface {
	ListCatalog(context.Context, *ListCatalogRequest) (*ListCatalogResponse, error)
	// ADMIN.
	SaveCatalogItem(context.Context, *CatalogItem) (*CatalogItem, error)
	ListRetainerDiscounts(context.Context, *emptypb.Empty) (*RetainerDiscounts, error)
	// ADMIN. Replaces every rule.
	SaveRetainerDiscounts(context.Context, *RetainerDiscounts) (*RetainerDiscounts, error)
	ListQuotations(context.Context, *ListQuotationsRequest) (*ListQuotationsResponse, error)
	GetQuotation(context.Context, *IdRequest) (*Quotation, error)
	CreateQuotation(context.Context, *QuotationInput) (*Quotation, error)
	// Draft only.
	UpdateQuotation(context.Context, *QuotationInput) (*Quotation, error)
	// terkirim | diterima | ditolak (send is blocked while a discount waits
	// for approval).
	SetQuotationStatus(context.Context, *SetQuotationStatusRequest) (*Quotation, error)
	// Copies items and terms into version + 1; the old version is superseded.
	ReviseQuotation(context.Context, *IdRequest) (*Quotation, error)
	DeleteQuotation(context.Context, *IdRequest) (*emptypb.Empty, error)
	// Builds a draft from the deal's service lines, the catalog, package
	// tiers and retainer discounts; OpenRouter (or the mock) writes scope
	// descriptions from the deal notes when use_ai is set.
	GenerateQuotationDraft(context.Context, *GenerateQuotationDraftRequest) (*GenerateQuotationDraftResponse, error)
	// Internal: PDF bytes for the gateway (GET /api/sales/quotations/{id}/pdf).
	RenderQuotationPdf(context.Context, *IdRequest) (*File, error)
	ListApprovalRules(context.Context, *emptypb.Empty) (*ListApprovalRulesResponse, error)
	// ADMIN.
	SaveApprovalRule(context.Context, *ApprovalRule) (*ApprovalRule, error)
	DeleteApprovalRule(context.Context, *IdRequest) (*emptypb.Empty, error)
	ListApprovals(context.Context, *ListApprovalsRequest) (*ListApprovalsResponse, error)
	// sales.approve (or the named approver).
	DecideApproval(context.Context, *DecideApprovalRequest) (*DecideApprovalResponse, error)
	mustEmbedUnimplementedQuotationServiceServer()
}

