	// signature and an audit footer).
	RenderContractPdf(context.Context, *RenderContractPdfRequest) (*File, error)
	// Public, no auth: the contract behind an unguessable token.
	GetPublicContract(context.Context, *PublicContractRequest) (*PublicContract, error)
	// Public, no auth, rate limited: typed name + drawn signature (PNG data
	// URL). IP and user agent come from the request metadata.
	SignPublicContract(context.Context, *SignPublicContractRequest) (*PublicContract, error)
